-- Frozen ICU 78.3 Han-Latin initials; regenerate only as a reviewed migration change.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS eb_member_pinyin_char_initial (
  hanzi VARCHAR(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL PRIMARY KEY,
